{"rob": "robolang 1.3;

task transfer(robot r, object vial, location src, location dst, region hood) {
    @safety max_speed 0.4 m/s;
    pre { region_clear hood; }
    goal { object_at vial dst; }
    plan {
        move r to src;
        grasp r vial;
        move r to dst;
        place r vial at dst;
    }
}
", "task": "transfer", "bindings": [{"param": "r", "id": "arm1"}, {"param": "vial", "id": "vial2"}, {"param": "src", "id": "fridge"}, {"param": "dst", "id": "bench"}, {"param": "hood", "id": "hood"}]}
